// === NODE 2: CONVERT TO BASE64 ===

const body = $item(0).$node["Webhook Vision"].json.body;
const binaryData = $input.first().binary.data;

if (!binaryData) {
  throw new Error('No image data received');
}

// Get mime type from binary data or default to jpeg
const mimeType = binaryData.mimeType || 'image/jpeg';

// Convert buffer to base64
const base64 = binaryData.data.toString('base64');

// Create data URL for Vision API
const dataUrl = `data:${mimeType};base64,${base64}`;

// Extract metadata
const chatId = body.chatId;
const messageId = body.messageId;
const sessionId = body.sessionId;
const caption = body.caption || '';

console.log('[VISION] Image converted:', {
  chatId,
  messageId,
  mimeType,
  size: base64.length,
  hasCaption: caption.length > 0
});

return {
  json: {
    imageDataUrl: dataUrl,
    chatId: chatId,
    messageId: messageId,
    sessionId: sessionId,
    caption: caption,
    mimeType: mimeType,
    timestamp: new Date().toISOString()
  }
};

// === NODE 4: BUILD CONTEXTUALIZED PROMPT ===

const visionResult = $input.first().json.text;
const prevData = $item("0").$node["2. Convert to Base64"].json;

// System prompt for contextualized response
const systemPrompt = `Você é assistente virtual do escritório Dr. Dênis Bernardo.

⚠️ IMPORTANTE: Cliente enviou uma IMAGEM (não texto digitado).
- A descrição abaixo é análise de Vision AI da imagem
- Responda de forma natural sobre o que o cliente mostrou
- Confirme que você viu a imagem

REGRAS:
1. Tom: Informal, empático, como vizinho de confiança
2. Linguagem: Português simples, máx 2-3 frases
3. Sempre confirme que viu a imagem: "Vi sua foto! ..."
4. Se cliente enviou legenda, considere no contexto

💬 EXEMPLO:
Cliente: [foto de documento] + legenda "Preciso tirar dúvida sobre isso"
Você: "Vi o documento! Posso te ajudar. Do que se trata?"

NUNCA invente informações.
Sempre termine: "Precisa de mais alguma coisa?"`;

// User prompt with Vision analysis
const userPrompt = `📷 ANÁLISE DA IMAGEM:
${visionResult}

${prevData.caption ? `LEGENDA DO CLIENTE: "${prevData.caption}"\n\n` : ''}Responda ao cliente confirmando que viu a imagem e ajude conforme necessário.`;

return {
  json: {
    systemPrompt: systemPrompt,
    userPrompt: userPrompt,
    chatId: prevData.chatId,
    messageId: prevData.messageId,
    visionAnalysis: visionResult
  }
};

// === NODE 6: CLEAN RESPONSE ===

let text = $input.first().json.text;

// Remove thinking tags if present
text = text.replace(/<think>[\s\S]*?<\/think>/g, '').trim();

// Get chat data
const prevData = $item("0").$node["4. Build Contextualized Prompt"].json;

return {
  json: {
    chatId: prevData.chatId,
    text: text,
    messageId: prevData.messageId,
    wasImage: true
  }
};
